    @Transient
    public Integer getCheckDigit() {
        if (this.customerCode == null) {
            return null;
        }
        String code = this.customerCode;
        int sum = 0;
        boolean dbl = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
